{
  "book_code": "2ES",
  "verses": [
    {
      "text_ar": "الذي عرشه لا يُقاس، والذي مجده لا يُدرك، والذي تقف أمامه جيوش الملائكة مرتعشة،",
      "chapter": 8,
      "verse": 21
    },
    {
      "text_ar": "الذي بأمره يتحولون إلى ريح ونار، وكلمته ثابتة، وأقواله راسخة، وأمرك قوي، ووصيتهم مخيفة،",
      "chapter": 8,
      "verse": 22
    },
    {
      "text_ar": "الذي بنظراته تجف الأعماق، وغضبه يذيب الجبال، وحقُّه يشهد،",
      "chapter": 8,
      "verse": 23
    },
    {
      "text_ar": "فاسمع يا رب صلاة عبدك، وأصغِ إلى التماس صنع يديك.",
      "chapter": 8,
      "verse": 24
    },
    {
      "text_ar": "انتبه إلى كلامي، لأنه طالما أعيش سأتكلم، وطالما لي فهمٌ سأجيب.",
      "chapter": 8,
      "verse": 25
    },
    {
      "text_ar": "لا تنظر إلى خطايا شعبك، بل إلى الذين خدموك بالحق.",
      "chapter": 8,
      "verse": 26
    },
    {
      "text_ar": "لا تلتفت إلى أفعال صانعي الشر، بل إلى الذين حفظوا عهودك في الضيق.",
      "chapter": 8,
      "verse": 27
    },
    {
      "text_ar": "لا تفكر في الذين سلكوا بطريقة شريرة أمامك، بل اذكر الذين عرفوا مخافتك بطوعهم.",
      "chapter": 8,
      "verse": 28
    },
    {
      "text_ar": "ليكن ليس في إرادتك أن تهلك الذين عاشوا مثل البهائم، بل انظر إلى الذين علموا شريعتك بوضوح.",
      "chapter": 8,
      "verse": 29
    },
    {
      "text_ar": "لا تغضب على الذين يُحسبون أسوأ من الحيوانات، بل أحب الذين وضعوا ثقتهم دائماً في مجدك.",
      "chapter": 8,
      "verse": 30
    },
    {
      "text_ar": "لأننا نحن وآباءنا قضينا حياتنا في طرق تجلب الموت، أما أنت فتُدعى رحوماً من أجلنا نحن الخطاة.",
      "chapter": 8,
      "verse": 31
    },
    {
      "text_ar": "لأنه إن كانت لك رغبة في أن ترحمنا نحن الذين بلا أعمال برّ، فحينئذ ستُدعى رحوماً.",
      "chapter": 8,
      "verse": 32
    },
    {
      "text_ar": "لأن الأبرار الذين لديهم أعمال صالحة كثيرة مخزونة عندك، سيُجازون عن أعمالهم الخاصة.",
      "chapter": 8,
      "verse": 33
    },
    {
      "text_ar": "لأن ما هو الإنسان حتى تغضب عليه؟ أو ما هو نسل قابل للفساد حتى تقسو عليه هكذا؟",
      "chapter": 8,
      "verse": 34
    },
    {
      "text_ar": "لأنه بالحقيقة، ليس إنسان بين المولودين لم يصنع شراً، وبين الذين عاشوا، ليس من لم يرتكب خطأ.",
      "chapter": 8,
      "verse": 35
    },
    {
      "text_ar": "لأنه في هذا يا رب، سيُعلن برُّك وصلاحك، إن كنت رحوماً للذين ليس لهم رصيد من الأعمال الصالحة.",
      "chapter": 8,
      "verse": 36
    },
    {
      "text_ar": "ثم أجابني قائلاً: لقد تكلمت بأمور صحيحة، وسيكون الأمر بحسب كلامك.",
      "chapter": 8,
      "verse": 37
    },
    {
      "text_ar": "لأني حقاً لن أفكر في تكوين الذين أخطأوا، أو في موتهم أو دينونتهم أو هلاكهم؛",
      "chapter": 8,
      "verse": 38
    },
    {
      "text_ar": "بل سأفرح بخليقة الأبرار وريحتهم وخلاصهم والمكافأة التي سيحصلون عليها.",
      "chapter": 8,
      "verse": 39
    },
    {
      "text_ar": "لذلك كما تكلمت، هكذا سيكون.",
      "chapter": 8,
      "verse": 40
    }
  ]
}
